import {defaultLocale} from '@/model/content/Schema'
import type {Locale} from '@/model/content/Schema'

export const musicAppsRootPath = '/app/'

/**
 * Music Apps translates on its own schedule, so its languages are set by scripts/build-combined.mjs
 * from the built Music Apps artifact. Empty for a portal-only build.
 */
function musicAppsLocales(): string[] {
  const configured = process.env.VUE_APP_MUSIC_APPS_LOCALES
  return configured ? configured.split(',').filter(Boolean) : []
}

/** Music Apps root for `locale`, dropping to English when Music Apps has no such language. */
export function musicAppsRootPathFor(locale: Locale): string {
  if (locale === defaultLocale || !musicAppsLocales().includes(locale)) return musicAppsRootPath
  return `${musicAppsRootPath}${locale}/`
}
